<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$title=trim((string)($_POST['title']??''));$slug=trim((string)($_POST['slug']??''));$excerpt=trim((string)($_POST['excerpt']??''));$content=trim((string)($_POST['content']??''));$category=trim((string)($_POST['category']??'Product'));if(!$title||strlen($title)<4)$error='Add a title.';elseif(!$slug||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))$error='Use a lowercase URL slug.';elseif(!$excerpt||strlen($excerpt)<20)$error='Add a longer excerpt.';elseif(strlen(strip_tags($content))<100)$error='Add complete article content.';else{$safeContent=strip_tags($content,['p','br','strong','em','u','h1','h2','h3','blockquote','ul','ol','li','code','pre','a']);$posts=load_json('blog.json',[]);$posts[]= ['id'=>'post-'.bin2hex(random_bytes(8)),'slug'=>$slug,'title'=>$title,'excerpt'=>$excerpt,'content'=>$safeContent,'category'=>$category,'author'=>current_user()['username'],'date'=>date('c'),'featured'=>isset($_POST['featured'])];if(save_json('blog.json',$posts))$success='Post published.';else$error='The post could not be saved.';}}?>
